-- Los conceptos reutilizan rubro_presupuestal. FORM.CONCEPTO.* son identidades internas,
-- no códigos de la hoja FINAL. Los nombres repetidos mantienen filas independientes.
-- Retirar del formulario las plantillas anteriores sin solicitudes; no borrar datos ni mapeos.
UPDATE rubro_presupuestal SET activo = FALSE, updated_at = CURRENT_TIMESTAMP
WHERE categoria_formulacion = TRUE AND codigo LIKE 'FORM.%'
  AND NOT EXISTS (SELECT 1 FROM necesidad_presupuestal n WHERE n.rubro_presupuestal_id = rubro_presupuestal.id);

ALTER TABLE area_vigencia ADD COLUMN fecha_envio DATETIME(6);
ALTER TABLE area_vigencia ADD COLUMN enviado_por_id BIGINT;
ALTER TABLE area_vigencia ADD COLUMN datos_enviados LONGTEXT;
ALTER TABLE area_vigencia ADD CONSTRAINT fk_formulario_enviado_por FOREIGN KEY (enviado_por_id) REFERENCES usuario(id);

